    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RA_1RC1LA_1LD1RB_0RB0LD [SCycL 2 0; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
