    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RB_1RC0LA_1LD1RB_0RB0LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RB_1RC0LA_1LD1RB_0RB0LD : forall t, ~ In t pins_1RB1RB_1RC0LA_1LD1RB_0RB0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1RB_1RC0LA_1LD1RB_0RB0LD.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1RC0LA_1LD1RB_0RB0LD [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1RC0LA_1LD1RB_0RB0LD [SCycL 2 0; SWin 2; SWinL 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1RC0LA_1LD1RB_0RB0LD [SCycL 2 0; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1RC0LA_1LD1RB_0RB0LD [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1RC0LA_1LD1RB_0RB0LD [SCycL 2 0; SWin 2; SWinL 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtrm_1RB1RB_1RC0LA_1LD1RB_0RB0LD : NonHalt tmm_1RB1RB_1RC0LA_1LD1RB_0RB0LD /\ QHBoundTr 32779478 tmm_1RB1RB_1RC0LA_1LD1RB_0RB0LD /\ QuasiHaltsTr tmm_1RB1RB_1RC0LA_1LD1RB_0RB0LD.
Proof.
  apply (lap_qh_stage tmm_1RB1RB_1RC0LA_1LD1RB_0RB0LD pins_1RB1RB_1RC0LA_1LD1RB_0RB0LD Cc 2 20 32779478).
  - exact bootq_1RB1RB_1RC0LA_1LD1RB_0RB0LD.
  - intros p _. apply lap_1RB1RB_1RC0LA_1LD1RB_0RB0LD.
  - intros t Ht p _. apply fire_1RB1RB_1RC0LA_1LD1RB_0RB0LD. exact Ht.
  - exact wit_1RB1RB_1RC0LA_1LD1RB_0RB0LD.
  - apply qcleb_QE_07. reflexivity.
Qed.

Theorem qhtr_1RB1RB_1RC0LA_1LD1RB_0RB0LD : NonHalt tm_1RB1RB_1RC0LA_1LD1RB_0RB0LD /\ QHBoundTr 32779478 tm_1RB1RB_1RC0LA_1LD1RB_0RB0LD /\ QuasiHaltsTr tm_1RB1RB_1RC0LA_1LD1RB_0RB0LD.
