  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RD_1LC0RD_0LC1RD_0RB0LA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
