      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtrm_1RB1RD_1LC0RD_0LC1RD_0RB0LA : NonHalt tmm_1RB1RD_1LC0RD_0LC1RD_0RB0LA /\ QHBoundTr 32779478 tmm_1RB1RD_1LC0RD_0LC1RD_0RB0LA /\ QuasiHaltsTr tmm_1RB1RD_1LC0RD_0LC1RD_0RB0LA.
