  - exact bootq_1RB1RD_1LC0RD_0LC1RD_0RB0LA.
  - intros p _. apply lap_1RB1RD_1LC0RD_0LC1RD_0RB0LA.
  - intros t Ht p _. apply fire_1RB1RD_1LC0RD_0LC1RD_0RB0LA. exact Ht.
  - exact wit_1RB1RD_1LC0RD_0LC1RD_0RB0LA.
  - apply qcleb_QE_07. reflexivity.
Qed.

