Definition mk_1RB1RD_1LC1RA_0RB0LC_0LD0RC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1RD_1LC1RA_0RB0LC_0LD0RC.

(** 1RB1RD_1LC1RA_0RB0LC_0LD0RC *)
(** 1RB1RD_1LC1RA_0RB0LC_0LD0RC -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1RD_1LC1RA_0RB0LC_0LD0RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S0 DL StC
  | StD, S0 => mk S0 DL StD | StD, S1 => mk S0 DR StC end.

(** Its mirror 1LB1LD_1RC1LA_0LB0RC_0RD0LC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S0 DR StD | StD, S1 => mk S0 DL StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RD_1LC1RA_0RB0LC_0LD0RC : list Instr := [(StA, S1); (StD, S0); (StD, S1)].
Definition tmw_1RB1RD_1LC1RA_0RB0LC_0LD0RC : TM := tm_wrap_trs tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC pins_1RB1RD_1LC1RA_0RB0LC_0LD0RC.
Local Notation tm := tmw_1RB1RD_1LC1RA_0RB0LC_0LD0RC.

Lemma mirror_ok_1RB1RD_1LC1RA_0RB0LC_0LD0RC : mirror_tm tm_1RB1RD_1LC1RA_0RB0LC_0LD0RC = tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1RD_1LC1RA_0RB0LC_0LD0RC (p : positive) : cconf := (StC, (Ap_Alph_00_10_1 p ++ [S0], S0, [S0;S1])).
Local Notation Cc := Cc_1RB1RD_1LC1RA_0RB0LC_0LD0RC.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1RD_1LC1RA_0RB0LC_0LD0RC : sconf := mkC StC (mkS [S0;S0] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 []).
Definition Z1_1RB1RD_1LC1RA_0RB0LC_0LD0RC : sconf := mkC StC (mkS [S1;S0] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 []).
Definition chz_1RB1RD_1LC1RA_0RB0LC_0LD0RC : list lstep := [SWin 2].

Lemma run_z_1RB1RD_1LC1RA_0RB0LC_0LD0RC : srun tm false true chz_1RB1RD_1LC1RA_0RB0LC_0LD0RC Z0_1RB1RD_1LC1RA_0RB0LC_0LD0RC = Some (Z1_1RB1RD_1LC1RA_0RB0LC_0LD0RC, 0, 2).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_1RB1RD_1LC1RA_0RB0LC_0LD0RC : sconf := mkC StC (mkS [S1;S0] [S1;S0] 1 0 [S0;S0]) S0 (mkS [S0;S1] [] 0 0 []).
Definition P1_1RB1RD_1LC1RA_0RB0LC_0LD0RC : sconf := mkC StC (mkS [S0;S0] [S0;S0] 1 0 [S1;S0]) S0 (mkS [S0;S1] [] 0 0 []).
Definition chp_1RB1RD_1LC1RA_0RB0LC_0LD0RC : list lstep := [SWin 2; SCycL 2 0; SWin 2; SCycR 2; SWin 2].

Lemma run_p_1RB1RD_1LC1RA_0RB0LC_0LD0RC : srun tm false true chp_1RB1RD_1LC1RA_0RB0LC_0LD0RC P0_1RB1RD_1LC1RA_0RB0LC_0LD0RC = Some (P1_1RB1RD_1LC1RA_0RB0LC_0LD0RC, 4, 6).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1RD_1LC1RA_0RB0LC_0LD0RC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S0]) S0 (mkS [S0;S1] [] 0 0 []).
Definition B1_1RB1RD_1LC1RA_0RB0LC_0LD0RC : sconf := mkC StC (mkS [] [S0;S0] 1 1 [S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition cho_1RB1RD_1LC1RA_0RB0LC_0LD0RC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_ovf_1RB1RD_1LC1RA_0RB0LC_0LD0RC : srun tm true true cho_1RB1RD_1LC1RA_0RB0LC_0LD0RC B0_1RB1RD_1LC1RA_0RB0LC_0LD0RC = Some (B1_1RB1RD_1LC1RA_0RB0LC_0LD0RC, 4, 6).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RD_1LC1RA_0RB0LC_0LD0RC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_1RB1RD_1LC1RA_0RB0LC_0LD0RC /\
  cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_1RB1RD_1LC1RA_0RB0LC_0LD0RC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_00_10_1.cview_some_Alph_00_10_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RD_1LC1RA_0RB0LC_0LD0RC, cden, Z0_1RB1RD_1LC1RA_0RB0LC_0LD0RC, Z1_1RB1RD_1LC1RA_0RB0LC_0LD0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RD_1LC1RA_0RB0LC_0LD0RC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j P0_1RB1RD_1LC1RA_0RB0LC_0LD0RC /\
  cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j P1_1RB1RD_1LC1RA_0RB0LC_0LD0RC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_00_10_1.cview_some_Alph_00_10_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RD_1LC1RA_0RB0LC_0LD0RC, cden, P0_1RB1RD_1LC1RA_0RB0LC_0LD0RC, P1_1RB1RD_1LC1RA_0RB0LC_0LD0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RD_1LC1RA_0RB0LC_0LD0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RD_1LC1RA_0RB0LC_0LD0RC p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RD_1LC1RA_0RB0LC_0LD0RC Z0_1RB1RD_1LC1RA_0RB0LC_0LD0RC Z1_1RB1RD_1LC1RA_0RB0LC_0LD0RC 0 2
               run_z_1RB1RD_1LC1RA_0RB0LC_0LD0RC (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RD_1LC1RA_0RB0LC_0LD0RC p j' q0 E) as (HA & HB).
    exists (4 * j' + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RD_1LC1RA_0RB0LC_0LD0RC P0_1RB1RD_1LC1RA_0RB0LC_0LD0RC P1_1RB1RD_1LC1RA_0RB0LC_0LD0RC 4 6
               run_p_1RB1RD_1LC1RA_0RB0LC_0LD0RC (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1RD_1LC1RA_0RB0LC_0LD0RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RD_1LC1RA_0RB0LC_0LD0RC.
Proof.
  intros p j E. destruct (Alph_00_10_1.cview_none_Alph_00_10_1 p j E) as (H1 & _).
  unfold Cc_1RB1RD_1LC1RA_0RB0LC_0LD0RC, cden, B0_1RB1RD_1LC1RA_0RB0LC_0LD0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RD_1LC1RA_0RB0LC_0LD0RC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RD_1LC1RA_0RB0LC_0LD0RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_1LC1RA_0RB0LC_0LD0RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_00_10_1.cview_none_Alph_00_10_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RD_1LC1RA_0RB0LC_0LD0RC
             = (StC, (rep [S0;S0] (S j) ++ [S1], S0, [S0;S1]))).
  { unfold cden, B1_1RB1RD_1LC1RA_0RB0LC_0LD0RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S0] (S j) ++ [S1]) ++ [S0], S0, [S0;S1]))).
  { unfold Cc_1RB1RD_1LC1RA_0RB0LC_0LD0RC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RD_1LC1RA_0RB0LC_0LD0RC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1RD_1LC1RA_0RB0LC_0LD0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RD_1LC1RA_0RB0LC_0LD0RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RD_1LC1RA_0RB0LC_0LD0RC B0_1RB1RD_1LC1RA_0RB0LC_0LD0RC B1_1RB1RD_1LC1RA_0RB0LC_0LD0RC 4 6 p j' [] []).
    + exact run_ovf_1RB1RD_1LC1RA_0RB0LC_0LD0RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RD_1LC1RA_0RB0LC_0LD0RC p j' E).
    + exact (geo_1RB1RD_1LC1RA_0RB0LC_0LD0RC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1RD_1LC1RA_0RB0LC_0LD0RC : stepn tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC 12 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC 12 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC 12 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1RD_1LC1RA_0RB0LC_0LD0RC : existsb (fun tg => cfires tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC c0 12 tg) pins_1RB1RD_1LC1RA_0RB0LC_0LD0RC = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RD_1LC1RA_0RB0LC_0LD0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RD_1LC1RA_0RB0LC_0LD0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RD_1LC1RA_0RB0LC_0LD0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RD_1LC1RA_0RB0LC_0LD0RC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RD_1LC1RA_0RB0LC_0LD0RC : forall t, ~ In t pins_1RB1RD_1LC1RA_0RB0LC_0LD0RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RD_1LC1RA_0RB0LC_0LD0RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1RD_1LC1RA_0RB0LC_0LD0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RD_1LC1RA_0RB0LC_0LD0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RD_1LC1RA_0RB0LC_0LD0RC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RD_1LC1RA_0RB0LC_0LD0RC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RD_1LC1RA_0RB0LC_0LD0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtrm_1RB1RD_1LC1RA_0RB0LC_0LD0RC : NonHalt tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC /\ QHBoundTr 32779478 tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC /\ QuasiHaltsTr tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC.
Proof.
  apply (lap_qh_stage tmm_1RB1RD_1LC1RA_0RB0LC_0LD0RC pins_1RB1RD_1LC1RA_0RB0LC_0LD0RC Cc 1 12 32779478).
  - exact bootq_1RB1RD_1LC1RA_0RB0LC_0LD0RC.
  - intros p _. apply lap_1RB1RD_1LC1RA_0RB0LC_0LD0RC.
  - intros t Ht p _. apply fire_1RB1RD_1LC1RA_0RB0LC_0LD0RC. exact Ht.
  - exact wit_1RB1RD_1LC1RA_0RB0LC_0LD0RC.
  - apply qcleb_QE_07. reflexivity.
Qed.

Theorem qhtr_1RB1RD_1LC1RA_0RB0LC_0LD0RC : NonHalt tm_1RB1RD_1LC1RA_0RB0LC_0LD0RC /\ QHBoundTr 32779478 tm_1RB1RD_1LC1RA_0RB0LC_0LD0RC /\ QuasiHaltsTr tm_1RB1RD_1LC1RA_0RB0LC_0LD0RC.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB1RD_1LC1RA_0RB0LC_0LD0RC). rewrite mirror_ok_1RB1RD_1LC1RA_0RB0LC_0LD0RC. exact qhtrm_1RB1RD_1LC1RA_0RB0LC_0LD0RC. Qed.

End B_QE_07_034.

